{"path": "/workspace/server.js", "content": "import { createServer as httpCreateServer } from "node:http";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { nanoid } from "nanoid";

/**
 * In-memory + JSON-file backed list of books.
 * Schema: { id, title, author, notes, status: "reading"|"finished", addedAt, finishedAt }
 */
function createStore(dataFile) {
  let books = [];
  let loaded = false;

  async function load() {
    if (loaded) return books;
    loaded = true;
    try {
      const raw = await readFile(dataFile, "utf8");
      books = JSON.parse(raw);
      if (!Array.isArray(books)) books = [];
    } catch {
      books = [];
    }
    return books;
  }

  async function persist() {
    await mkdir(dirname(dataFile), { recursive: true });
    await writeFile(dataFile, JSON.stringify(books, null, 2), "utf8");
  }

  return {
    async all() {
      await load();
      return books;
    },
    async get(id) {
      await load();
      return books.find((b) => b.id === id) || null;
    },
    async add({ title, author, notes, status }) {
      await load();
      const book = {
        id: nanoid(10),
        title: title.trim(),
        author: author.trim(),
        notes: notes ?? "",
        status: status === "finished" ? "finished" : "reading",
        addedAt: new Date().toISOString(),
        finishedAt: status === "finished" ? new Date().toISOString() : null,
      };
      books.push(book);
      await persist();
      return book;
    },
    async updateNotes(id, notes) {
      await load();
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.notes = notes ?? "";
      await persist();
      return book;
    },
    async markFinished(id) {
      await load();
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
      await persist();
      return book;
    },
  };
}

function esc(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  :root { color-scheme: light; }
  body { font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 680px; margin: 2rem auto; padding: 0 1rem; color: #1a1a1a; }
  h1 { font-size: 1.5rem; margin: 0 0 1.5rem; }
  h2 { font-size: 1.15rem; margin: 2rem 0 0.75rem; border-bottom: 1px solid #eee; padding-bottom: 0.25rem; }
  a { color: #2563eb; text-decoration: none; }
  a:hover { text-decoration: underline; }
  .book { padding: 0.6rem 0; }
  .book .title { font-weight: 600; }
  .book .author { color: #666; }
  .muted { color: #888; font-size: 0.9rem; }
  form { margin: 0.5rem 0; }
  label { display: block; margin: 0.6rem 0 0.15rem; font-weight: 600; font-size: 0.9rem; }
  input[type=text], textarea, select { width: 100%; box-sizing: border-box; padding: 0.45rem; border: 1px solid #ccc; border-radius: 6px; font: inherit; }
  textarea { min-height: 6rem; resize: vertical; }
  button { background: #2563eb; color: #fff; border: 0; border-radius: 6px; padding: 0.45rem 0.9rem; cursor: pointer; font: inherit; }
  button.secondary { background: #e5e7eb; color: #1a1a1a; }
  .row { display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap; }
  .pill { font-size: 0.75rem; padding: 0.1rem 0.45rem; border-radius: 999px; background: #eef2ff; color: #3730a3; }
  .pill.done { background: #ecfdf5; color: #065f46; }
  .share { font-size: 0.85rem; color: #888; font-family: ui-monospace, monospace; }
  nav a { margin-right: 1rem; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookRow(book, req) {
  const host = req?.headers?.host || "localhost";
  const url = `http://${host}/books/${book.id}`;
  const pill = book.status === "finished"
    ? `<span class="pill done">finished</span>`
    : `<span class="pill">reading</span>`;
  const finishBtn = book.status === "finished"
    ? ""
    : `<form method="post" action="/books/${esc(book.id)}/finish" style="display:inline;margin:0">
         <button class="secondary" type="submit">Mark finished</button>
       </form>`;
  return `<div class="book">
    <div class="row">
      <a class="title" href="/books/${esc(book.id)}">${esc(book.title)}</a>
      ${pill}
    </div>
    <div class="author">by ${esc(book.author || "Unknown")}</div>
    <div class="row" style="margin-top:0.35rem">
      ${finishBtn}
      <span class="share">share: ${esc(url)}</span>
    </div>
  </div>`;
}

function homePage(books, req) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books.filter((b) => b.status === "finished");

  const readingHtml = reading.length
    ? reading.map((b) => bookRow(b, req)).join("")
    : `<p class="muted">Nothing yet. Add a book below.</p>`;

  const finishedHtml = finished.length
    ? finished.map((b) => bookRow(b, req)).join("")
    : `<p class="muted">No finished books yet.</p>`;

  const form = `<h2>Add a book</h2>
<form method="post" action="/books">
  <label for="title">Title</label>
  <input id="title" name="title" type="text" required>
  <label for="author">Author</label>
  <input id="author" name="author" type="text">
  <label for="notes">Notes</label>
  <textarea id="notes" name="notes"></textarea>
  <label for="status">Status</label>
  <select id="status" name="status">
    <option value="reading" selected>Currently reading</option>
    <option value="finished">Finished</option>
  </select>
  <div style="margin-top:0.9rem"><button type="submit">Add book</button></div>
</form>`;

  return layout("Reading list", `
  <h1>📚 Reading list</h1>
  <h2>Currently reading</h2>
  ${readingHtml}
  <h2>Finished</h2>
  ${finishedHtml}
  ${form}
  `);
}

function detailPage(book, req) {
  const host = req?.headers?.host || "localhost";
  const url = `http://${host}/books/${book.id}`;
  const statusPill = book.status === "finished"
    ? `<span class="pill done">finished</span>`
    : `<span class="pill">reading</span>`;
  const finishBtn = book.status === "finished"
    ? ""
    : `<form method="post" action="/books/${esc(book.id)}/finish" style="display:inline;margin:0">
         <button class="secondary" type="submit">Mark finished</button>
       </form>`;
  return layout(book.title, `
  <nav><a href="/">← Back to list</a></nav>
  <h1>${esc(book.title)} ${statusPill}</h1>
  <p class="author">by ${esc(book.author || "Unknown")}</p>
  <p class="share">Shareable link: <a href="${esc(url)}">${esc(url)}</a></p>

  <h2>Notes</h2>
  <form method="post" action="/books/${esc(book.id)}/notes">
    <textarea name="notes" placeholder="Your notes...">${esc(book.notes)}</textarea>
    <div style="margin-top:0.6rem"><button type="submit">Save notes</button></div>
  </form>

  <div style="margin-top:1.5rem">${finishBtn}</div>
  `);
}

/** Read a urlencoded form body, capped to a small size. */
function readForm(req, limit = 100_000) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (c) => {
      size += c.length;
      if (size > limit) {
        reject(new Error("body too large"));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      const params = new URLSearchParams(raw);
      const obj = {};
      for (const [k, v] of params.entries()) obj[k] = v;
      resolve(obj);
    });
    req.on("error", reject);
  });
}

function send(res, status, html) {
  res.statusCode = status;
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.end(html);
}

export function createApp({ dataFile = "books.json" } = {}) {
  const store = createStore(dataFile);

  const server = httpCreateServer(async (req, res) => {
    try {
      const url = new URL(req.url, "http://localhost");
      const path = url.pathname;

      if (req.method === "GET" && path === "/") {
        const books = await store.all();
        return send(res, 200, homePage(books, req));
      }

      const detail = /^\/books\/([^/]+)$/.exec(path);
      if (req.method === "GET" && detail) {
        const book = await store.get(detail[1]);
        if (!book) return send(res, 404, layout("Not found", `<h1>Book not found</h1><p><a href="/">Back to list</a></p>`));
        return send(res, 200, detailPage(book, req));
      }

      if (req.method === "POST" && path === "/books") {
        const f = await readForm(req);
        if (!f.title || !f.title.trim()) {
          return send(res, 400, layout("Missing title", `<h1>Title is required</h1><p><a href="/">Back</a></p>`));
        }
        await store.add(f);
        return send(res, 303, "") || void (res.setHeader("Location", "/"), res.end());
      }

      const notes = /^\/books\/([^/]+)\/notes$/.exec(path);
      if (req.method === "POST" && notes) {
        const f = await readForm(req);
        const book = await store.updateNotes(notes[1], f.notes ?? "");
        if (!book) return send(res, 404, layout("Not found", `<h1>Book not found</h1>`));
        res.statusCode = 303;
        res.setHeader("Location", `/books/${book.id}`);
        return res.end();
      }

      const finish = /^\/books\/([^/]+)\/finish$/.exec(path);
      if (req.method === "POST" && finish) {
        const book = await store.markFinished(finish[1]);
        if (!book) return send(res, 404, layout("Not found", `<h1>Book not found</h1>`));
        res.statusCode = 303;
        res.setHeader("Location", `/books/${book.id}`);
        return res.end();
      }

      return send(res, 404, layout("Not found", `<h1>Not found</h1><p><a href="/">Home</a></p>`));
    } catch (err) {
      console.error(err);
      return send(res, 500, layout("Error", `<h1>Something went wrong</h1><pre>${esc(err.message)}</pre>`));
    }
  });

  return server;
}

const isMain = process.argv[1] && import.meta.url === `file://${process.argv[1]}`;
if (isMain) {
  const port = Number(process.env.PORT) || 3000;
  const dataFile = process.env.BOOKS_FILE || "books.json";
  const server = createApp({ dataFile });
  server.listen(port, () => {
    console.log(`Reading list app running at http://localhost:${port} (data: ${dataFile})`);
  });
}
"}

