{"content": "import { test, expect, afterAll } from "vitest";
import { createApp } from "../server.js";
import { mkdtempSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

const dir = mkdtempSync(join(tmpdir(), "books-"));
afterAll(() => rmSync(dir, { recursive: true, force: true }));

const server = createApp({ dataFile: join(dir, "books.json") });
await new Promise((r) => server.listen(0, r));
const base = `http://localhost:${server.address().port}`;
afterAll(() => new Promise((r) => server.close(r)));

const form = (obj) =>
  new URLSearchParams(obj).toString();

test("add a book, see it on home, mark finished, view detail", async () => {
  // Home starts empty of reading books.
  let home = await (await fetch(base)).text();
  expect(home).toContain("Nothing yet. Add a book below.");

  // Add a book that is currently reading.
  const addRes = await fetch(base + "/books", {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: form({ title: "The Pragmatic Programmer", author: "Hunt & Thomas", notes: "ch.1", status: "reading" }),
    redirect: "manual",
  });
  expect(addRes.status).toBe(303);
  expect(addRes.headers.get("location")).toBe("/");

  // It now appears under "Currently reading".
  home = await (await fetch(base)).text();
  expect(home).toContain("The Pragmatic Programmer");
  expect(home).toContain("by Hunt &amp; Thomas");
  expect(home).toContain("Mark finished");

  // Grab the detail link and share url.
  const idMatch = home.match(/\/books\/([A-Za-z0-9_-]+)/);
  expect(idMatch).not.toBeNull();
  const id = idMatch[1];

  // Detail page shows title, author, notes.
  const detail = await (await fetch(base + "/books/" + id)).text();
  expect(detail).toContain("The Pragmatic Programmer");
  expect(detail).toContain("Hunt &amp; Thomas");
  expect(detail).toContain("ch.1");
  expect(detail).toContain(`/books/${id}`);

  // Mark finished -> redirects to detail.
  const finRes = await fetch(base + `/books/${id}/finish`, {
    method: "POST",
    redirect: "manual",
  });
  expect(finRes.status).toBe(303);
  expect(finRes.headers.get("location")).toBe(`/books/${id}`);

  // Home now lists it under Finished, not Currently reading, and no Mark finished button.
  home = await (await fetch(base)).text();
  const finishedSection = home.split("Finished")[1];
  expect(finishedSection).toContain("The Pragmatic Programmer");
  expect(home.split("Currently reading")[1].split("Finished")[0]).not.toContain("The Pragmatic Programmer");
});

test("notes can be edited", async () => {
  const addRes = await fetch(base + "/books", {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: form({ title: "Deep Work", author: "Cal Newport", notes: "", status: "reading" }),
    redirect: "manual",
  });
  expect(addRes.status).toBe(303);

  const home = await (await fetch(base)).text();
  const id = home.match(/\/books\/([A-Za-z0-9_-]+)/)[1];

  const saveRes = await fetch(base + `/books/${id}/notes`, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: form({ notes: "focus is rare" }),
    redirect: "manual",
  });
  expect(saveRes.status).toBe(303);

  const detail = await (await fetch(base + "/books/" + id)).text();
  expect(detail).toContain("focus is rare");
});

test("unknown book id returns 404", async () => {
  const res = await fetch(base + "/books/does-not-exist");
  expect(res.status).toBe(404);
});

test("adding without a title is rejected", async () => {
  const res = await fetch(base + "/books", {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: form({ title: "   ", author: "x" }),
    redirect: "manual",
  });
  expect(res.status).toBe(400);
});
